Ltac brute_regZ2 n r lo cnt g :=
  let w := getreg n in
  lazymatch w with
  | Z_to_bv 64 ?e =>
      let F := eval pattern r in e in
      lazymatch F with
      | ?f r =>
          let H := fresh "BR" in
          assert (H : forall r0, lo <= r0 < lo + cnt -> (f r0 =? g r0) = true)
            by (apply (brute_range (fun r0 => f r0 =? g r0) lo cnt); vm_compute; reflexivity);
          replace e with (g r) by (symmetry; apply Z.eqb_eq; apply H; lia);
          clear H
      end
  | _ => fail "brute_regZ2: register" n "holds" w
  end.

(* [comment removed for export] *)
Fixpoint cells_upd (m' : amem) (W : list ivl) (A : Z) (cs cs' : list cell) {struct cs} : Prop :=
  match cs, cs' with
  | c :: cs1, c' :: cs1' =>
      (csize c' = csize c /\ ((c' = c /\ disjoint_from W A (Z.of_nat (csize c))) \/ rw_cells asegs m' A [c'])) /\
      match cs1, cs1' with
      | [], [] => True
      | _, _ => cells_upd m' W (A + Z.of_nat (csize c)) cs1 cs1'
      end
  | _, _ => False
  end.

Lemma w4s_cells_upd : forall W m m', munch W m m' -> wmono asegs m m' ->
  forall cs A cs', rw_cells asegs m A cs -> cells_upd m' W A cs cs' -> rw_cells asegs m' A cs'.
