(* [comment removed for export] *)
Lemma w4s_sjoin2 : forall (RNG : footprint) (Q : machine_state -> Prop) (mm : amem) (r l P : Z) (w96 w104 w200 w208 w224 : word)
    (ra gp tp x5 x6 x7 x8 x9 a0 a2 a3 a4 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32),
  rw_cells asegs mm (P + 96) [C8 w96] -> rw_cells asegs mm (P + 104) [C8 w104] -> rw_cells asegs mm (P + 200) [C8 w200] ->
  rw_cells asegs mm (P + 208) [C8 w208] -> rw_cells asegs mm (P + 224) [C8 w224] ->
  mem_inv asegs mm -> rng RNG P 496 ->
  rng_aimg RNG -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> 1 <= r <= 255 -> 1 <= l <= 7 ->
  (forall mm' (a1' a2' a5' a6' : word),
     munch [(P + 96, P + 112); (P + 200, P + 216); (P + 224, P + 232)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     rw_cells asegs mm' (P + 96) [C8 s3] -> rw_cells asegs mm' (P + 104) [C8 t3] -> rw_cells asegs mm' (P + 200) [C8 t4] ->
     rw_cells asegs mm' (P + 208) [C8 s5] -> rw_cells asegs mm' (P + 224) [C8 a4] ->
     evtF asegs RNG Q (MS (mkR ra (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 a0 a1' a2' a3 a4 a5' a6' a7 s2 s3 s4
                              (Z_to_bv 64 (72 - Z.log2 r - 8 * l)) s6 s7 s8 s2 s10 s11 t3 t4 t5 t6)
                         F (Z_to_bv 64 0x908b8) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR ra (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 a0 (Z_to_bv 64 r) a2 a3 a4 (Z_to_bv 64 l) a6 a7
                           s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
