(* [comment removed for export] *)
Ltac w4s_upd_cell :=
  first [ left; split; [reflexivity | cbn [disjoint_from]; lia]
        | right;
          lazymatch goal with |- rw_cells ?sg ?m ?X [?c] =>
            match goal with H : rw_cells sg m ?Y [c] |- _ => replace X with Y by lia; exact H end end ].
Ltac w4s_upd_solve :=
  cbn [cells_upd csize];
  repeat match goal with
  | |- _ /\ _ => split
  | |- True => exact I
  | |- (?n = ?n)%nat => reflexivity
  | |- (_ = _ /\ _) \/ _ => w4s_upd_cell
  end.

